package com.abhishek.ecommerce.order;import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.UUID;@FeignClient(name="product-service")public interface ProductClient{@GetMapping("/api/products/{id}")ProductView get(@PathVariable UUID id);@PostMapping("/api/products/{id}/reserve")ProductView reserve(@PathVariable UUID id,@RequestParam int quantity);record ProductView(UUID id,String sku,String name,String category,BigDecimal price,int stock,boolean active){}}